def remove_func(lines,name):
    idx=[i for i,l in enumerate(lines) if l.startswith('function '+name+'(')]
    assert len(idx)==1,(name,idx)
    i=idx[0];j=i+1
    while j<len(lines) and (lines[j].startswith(' ') or lines[j].startswith('}') or lines[j]==''):
        if lines[j]=='' : break
        j+=1
    del lines[i:j]
    return i
